<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Notification\SmtpOutboundConfig\Domain\Gateway;

use Civi\Lughauth\Features\Notification\SmtpOutboundConfig\Domain\SmtpOutboundConfig;

class SmtpOutboundConfigCursor
{
    public function __construct(
        private int $limit,
        private ?string $sinceUid = null,
    ) {
    }
    public function next(SmtpOutboundConfig $smtpOutboundConfig, ?int $size): SmtpOutboundConfigCursor
    {
        $next = clone $this;
        $next->sinceUid = $smtpOutboundConfig->uid();
        $next->limit = $size ?? $this->limit;
        return $next;
    }
    public function limit(): int
    {
        return $this->limit;
    }
    public function sinceUid(): ?string
    {
        return $this->sinceUid;
    }
}
